import { createDarkTheme, createLightTheme, type BrandVariants, type Theme } from '@fluentui/react-components';

/**
 * The xrmverse brand ramp (legal §6 identity), generated by the user with the Fluent theme designer on 2026-11-17 when the
 * UI moved to plain Fluent UI: 10 darkest, 160 lightest, brand colour #895B1F at 80. It is the only place in the UI that
 * holds colour values; components use Fluent `tokens` (enforced by `noHardcodedColors.test.ts`).
 */
export const xrmverseBrand: BrandVariants = {
  10: '#050300',
  20: '#211605',
  30: '#362308',
  40: '#472C08',
  50: '#593707',
  60: '#6B4103',
  70: '#7D4D05',
  80: '#895B1F',
  90: '#966934',
  100: '#A27848',
  110: '#AE875C',
  120: '#BA9771',
  130: '#C5A686',
  140: '#D0B69B',
  150: '#DBC6B1',
  160: '#E6D7C8',
};

/** The system font stack (no Segoe UI). */
export const systemFontStack = "system-ui, -apple-system, 'Helvetica Neue', Arial, sans-serif";

/** The xrmverse brand font (Sora, OFL-1.1, bundled by main.tsx) with the system font stack as fallback. */
export const brandFontStack = "'Sora Variable', " + systemFontStack;

const fonts = {
  fontFamilyBase: brandFontStack,
  fontFamilyNumeric: systemFontStack,
  fontFamilyMonospace: "ui-monospace, 'SFMono-Regular', Menlo, Consolas, 'Liberation Mono', monospace",
  /** Sora at 400 reads heavier than the usual UI fonts: regular text uses the variable font's 300 (light) weight. */
  fontWeightRegular: 300,
} as const;

/**
 * The xrmverse light theme, used by the web admin and the model-driven apps alike: Fluent's own `createLightTheme` on the
 * brand ramp, with only the fonts (family and regular weight) replaced (§6: no Segoe UI). No colour token is overridden.
 */
export const xrmverseTheme: Theme = { ...createLightTheme(xrmverseBrand), ...fonts };

/**
 * Fluent's `createDarkTheme` on a brand ramp, with the two brand foregrounds lightened for contrast as the theme designer
 * suggests, and the xrmverse fonts. Shared by the xrmverse dark theme and custom-ramp overlays.
 */
export function createXrmverseDarkTheme(brand: BrandVariants): Theme {
  return { ...createDarkTheme(brand), ...fonts, colorBrandForeground1: brand[110], colorBrandForeground2: brand[120] };
}

/** The dark theme (operating system in dark mode): the xrmverse ramp through {@link createXrmverseDarkTheme}. */
export const xrmverseDarkTheme: Theme = createXrmverseDarkTheme(xrmverseBrand);

/** The xrmverse light theme on a custom brand ramp, with the xrmverse fonts. */
export function createXrmverseLightTheme(brand: BrandVariants): Theme {
  return { ...createLightTheme(brand), ...fonts };
}

/** Text colours on a choice value's background colour: {@link CHOICE_TEXT_DARK} or {@link CHOICE_TEXT_LIGHT}, whichever contrasts more. */
export const CHOICE_TEXT_DARK = '#000000';
export const CHOICE_TEXT_LIGHT = '#FFFFFF';
/** The colour a choice colour picker starts from when the option has none yet. */
export const CHOICE_DEFAULT_BACKGROUND = '#E1DFDD';
